""" Returns True if the considered string is a valid RIPEMD160 hash. """
def is_hash160(s: Any) -> object {
    if (not s or not isinstance(s, str)) {
        return False;
    }
    if not (len(s) == 40) {
        return False;
    }
    for c in s {
        if (
            ((c < '0') or (c > '9'))
            and ((c < 'A') or (c > 'F'))
            and ((c < 'a') or (c > 'f'))
        ) {
            return False;
        }
    }
    return True;
}

